const createMeetingMasterId=function(date,rows){
 const key=String(date||new Date().toISOString().slice(0,10)).slice(0,10).replace(/-/g,"");
 const used=(rows||[]).map(function(r){return String((r.data||{}).meetingMasterId||"");}).filter(function(x){return x.indexOf("SSF-MTG-"+key+"-")===0;}).map(function(x){const m=x.match(/-(\\d+)$/);return m?Number(m[1]):0;});
 return "SSF-MTG-"+key+"-"+String(Math.max(0,...used)+1).padStart(3,"0");
};
const legacyMeetingMasterId=function(date,recordId){
 const key=String(date||"").slice(0,10).replace(/-/g,"")||"00000000";
 const suffix=String(recordId||"").replace(/[^a-zA-Z0-9]/g,"").slice(-8)||"LEGACY";
 return "SSF-MTG-"+key+"-L"+suffix;
};
