    <div className="md:col-span-2"><div className="flex flex-wrap items-center justify-between gap-2 mb-2"><div><div className="font-black text-[#002344]">Meeting Participants / Meeting Members</div><p className="text-xs text-zinc-500 mt-1">Members with email can be selected; selected members will be used for the meeting invitation.</p></div><div className="flex gap-2"><button type="button" onClick={()=>setSelected(members.filter(r=>(r.data||{}).email).map(r=>r.id))} className="px-3 py-2 rounded-lg border border-[#1F7A70] text-[#1F7A70] font-bold text-xs">Select All / सभी चुनें</button><button type="button" onClick={()=>setSelected([])} className="px-3 py-2 rounded-lg border text-xs font-bold">Clear / हटाएँ</button></div></div><div className="text-xs text-[#123B5D] font-semibold mb-2">Selected: {selected.length} · With email: {members.filter(r=>(r.data||{}).email).length}</div><div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-2 max-h-64 overflow-auto">{members.length===0?<div className="text-sm text-zinc-500">No members found.</div>:members.map(r=>{const d=r.data||{};const email=d.email||"";return <label key={r.id} className={"flex items-center gap-2 border rounded-xl p-3 cursor-pointer "+(selected.includes(r.id)?"bg-zinc-100 border-[#002344]":"bg-white")}><input type="checkbox" checked={selected.includes(r.id)} onChange={()=>toggle(r.id)} disabled={!email}/><span><b>{d.fullName||d.name||"Member"}</b><small className="block text-zinc-500">{email||"No email — cannot send invitation"}</small></span></label>;})}</div></div>
