 const [notice,setNotice]=useState(""),[editingId,setEditingId]=useState(null),[saving,setSaving]=useState(false);
 const memberKey=r=>String(r?.recordId||r?.data?.memberId||r?.id||"");
 const statusForMember=r=>{const key=memberKey(r);const direct=attendanceStatus[String(r?.id||"")];if(direct)return direct;const alt=attendanceMembers.find(x=>memberKey(x)===key);return alt?(attendanceStatus[String(alt.id)]||"No Response"):"No Response";};
 const [followUpFilter,setFollowUpFilter]=useState("All Members"),[followUpRecipientId,setFollowUpRecipientId]=useState(""),[followUpMessage,setFollowUpMessage]=useState("");
 const buildFollowUpMessage=(member,status)=>{const name=String(member?.fullName||member?.name||"Member").trim();const title=String(f.meetingTitle||"SSF Meeting").trim();const date=String(f.meetingDate||"").slice(0,10);const purpose=String(f.purpose||"").trim();const agenda=String(f.agenda||"").trim();const subjectLine=purpose||agenda;let reason=status==="Did Not Attend"?"आप बैठक में उपस्थित नहीं हो सके।":status==="No Response"?"बैठक के संबंध में आपका response अभी प्राप्त नहीं हुआ है।":status==="Excused"?"आपकी अनुपस्थिति के संबंध में follow-up किया जा रहा है।":"बैठक के संबंध में कृपया अपना response साझा करें。";return ["Dear "+name+",","","This is a follow-up regarding the SSF meeting: "+title+(date?" on "+date:"")+"."+reason,(subjectLine?"Meeting purpose/agenda: "+subjectLine+".":""),"","कृपया अपनी उपलब्धता/प्रतिक्रिया साझा करें ताकि SSF के meeting record और आगे की कार्यवाही को update किया जा सके.","","Regards,","Swastik Srijan Foundation Samiti"].join("\n");};
