 useEffect(()=>{if(!followUpRecipientId)return;const m=memberOptions.find(r=>String(r.id)===String(followUpRecipientId));if(!m)return;const st=attendanceStatus[String(m.id)]||"No Response";setFollowUpMessage(buildFollowUpMessage(m,st));},[followUpRecipientId,attendanceStatus]);
 const sendFollowUp=async function(channel){if(!followUpRecipient){setNotice("Please select a follow-up member.");return;}const d=followUpRecipient.data||{};const mobile=String(d.mobile||d.phone||d.mobileNo||"").replace(/\\D/g,"");const email=String(d.email||"").trim();const msg=followUpMessage||"Please share your meeting response.";if(channel==="WhatsApp"){if(!mobile){setNotice("Selected member has no mobile number in the register.");return;}window.open("https://wa.me/"+(mobile.length===10?"91"+mobile:mobile)+"?text="+encodeURIComponent(msg),"_blank","noopener,noreferrer");setNotice("WhatsApp opened for "+(d.fullName||d.name||"member")+".");}else{if(!email){setNotice("Selected member has no email address in the register.");return;}window.location.href="mailto:"+email+"?subject="+encodeURIComponent("SSF Meeting Follow-up / बैठक अनुवर्ती कार्य")+"&body="+encodeURIComponent(msg);setNotice("Email composer opened for "+(d.fullName||d.name||"member")+".");}};

 useEffect(()=>{let alive=true;fetch(ENDPOINTS.DIGITAL_OFFICE_RECORDS+"?module=members",{headers:{Authorization:"Bearer "+token,"Content-Type":"application/json"}}).then(r=>r.ok?r.json():[]).then(d=>{if(!alive)return;const list=Array.isArray(d)?d:[];const normalized=list.map((r,i)=>{const d=r.data||r;return {id:String(r.id||r.recordId||d.memberId||"member-"+i),recordId:String(r.recordId||d.memberId||r.memberId||""),data:d};}).filter(r=>r.recordId||r.data?.fullName||r.data?.name);setMemberOptions(normalized.length?normalized:MEETING_MEMBER_OPTIONS.map(x=>({id:"master-"+x.memberId,recordId:x.memberId,data:x})));}).catch(()=>{if(alive)setMemberOptions(MEETING_MEMBER_OPTIONS.map(x=>({id:"master-"+x.memberId,recordId:x.memberId,data:x})));});return()=>{alive=false;};},[token]);
 useEffect(()=>{if(!calendarMeetingId||!memberOptions.length)return;const source=calendarRows.find(r=>String(r.id)===String(calendarMeetingId));if(!source)return;const d=source.data||{};let participants=[];try{participants=typeof d.participants==="string"?JSON.parse(d.participants):(Array.isArray(d.participants)?d.participants:[]);}catch(e){participants=[];}const ids=participants.map(x=>String(x.memberId||"")).filter(Boolean);if(ids.length)selectMeetingMembers(ids);},[memberOptions.length,calendarMeetingId,calendarRows.length]);
 const selectMeetingMembers=(ids)=>{const chosen=memberOptions.filter(r=>ids.includes(String(r.recordId||r.data?.memberId||r.id)));setSelectedMeetingMembers(ids);setAttendanceMembers(chosen);setAttendanceStatus(x=>{const n={};chosen.forEach(r=>{const id=String(r.id);n[id]=x[id]||"No Response";});return n;});};
 const setAttendance=(id,status)=>setAttendanceStatus(x=>({...x,[id]:status}));
