   const nonAttended=attendance.filter(x=>x.status==="Did Not Attend"||x.status==="No Response");
   const attended=attendance.filter(x=>x.status==="Attended");
   const payload={...f,meetingMasterId,meetingType:f.meetingType==="Other"?(f.meetingTypeOther||"Other"):f.meetingType,onlinePlatform:f.onlinePlatform==="Other"?(f.onlinePlatformOther||"Other"):f.onlinePlatform,date:f.meetingDate,sourceMeetingRecordId:calendarMeetingId||f.sourceMeetingRecordId||"",invitedParticipants:JSON.stringify(attendance.map(x=>({memberId:x.memberId,fullName:x.fullName,email:x.email||"",status:x.status}))),attendance:JSON.stringify(attendance),attendanceSummary:attendanceSummaryText(),presentMembers:attended.map(x=>x.fullName).join(", "),absentMembers:attendance.filter(x=>x.status==="Did Not Attend"||x.status==="Excused").map(x=>x.fullName).join(", "),followUpRequired:nonAttended.length?"Yes":f.followUpRequired,followUpStatus:nonAttended.length?"Pending":f.followUpStatus,followUpNotes:nonAttended.length?("Follow-up due for: "+nonAttended.map(x=>x.fullName).join(", ")):f.followUpNotes,followUpRecipientId:followUpRecipientId||"",followUpRecipientName:followUpRecipient?(followUpRecipient.data||{}).fullName||"":"",followUpRecipientMobile:followUpRecipient?(followUpRecipient.data||{}).mobile||"":"",followUpRecipientEmail:followUpRecipient?(followUpRecipient.data||{}).email||"":""};
   const ok=editingId?await updateRecord(editingId,"meetingResolutions",payload):await add("meetingResolutions",{recordDate:f.meetingDate,recordType:f.meetingType,status:"active",data:payload});
